create table orders (id int, status text);
create table cancelled (order_id int);
insert into orders values (1,'open'),(2,'shipped');
insert into cancelled values (1), (NULL);
select * from orders where id not in (select order_id from cancelled);
-- returns nothing, not the shipped row

select * from orders o where not exists (select 1 from cancelled c where c.order_id = o.id);
-- returns the shipped row as intended
NOT EXISTS is null-safe by design. Works the same in Postgres, MySQL, SQL Server, Oracle.
